import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class BankTransferService {
    private final AccountRepository accountRepo;

    public BankTransferService(AccountRepository accountRepo) {
        this.accountRepo = accountRepo;
    }

    @Transactional  // ACID wrapper: all four properties enforced
    public void transfer(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId).orElseThrow();
        var toAccount = accountRepo.findById(toId).orElseThrow();

        fromAccount.debit(amount);  // Atomicity: both or neither
        toAccount.credit(amount);

        accountRepo.save(fromAccount);  // Consistency: constraints checked
        accountRepo.save(toAccount);    // Isolation: locked from other txns
        // Durability: committed to WAL before returning
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final InventoryService inventoryService;

    public OrderService(OrderRepository orderRepo, InventoryService inventoryService) {
        this.orderRepo = orderRepo;
        this.inventoryService = inventoryService;
    }

    @Transactional  // Atomicity: all operations or none
    public Order placeOrder(Long productId, int quantity) {
        var order = new Order(productId, quantity);
        orderRepo.save(order);  // Inserted into database

        inventoryService.reduceStock(productId, quantity);  // If this throws exception...
        // ...the entire transaction rolls back automatically
        // Order insert is undone, database returns to pre-transaction state

        return order;  // Only reached if both operations succeed
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepo;
    private final AccountRepository accountRepo;

    public PaymentService(PaymentRepository paymentRepo, AccountRepository accountRepo) {
        this.paymentRepo = paymentRepo;
        this.accountRepo = accountRepo;
    }

    @Transactional  // Durability: commit persists to WAL
    public Payment processPayment(Long accountId, double amount) {
        var account = accountRepo.findById(accountId).orElseThrow();
        var payment = new Payment(accountId, amount, Instant.now());

        paymentRepo.save(payment);  // Written to database
        account.deductBalance(amount);
        accountRepo.save(account);

        // When method returns, Spring commits transaction
        // Database writes changes to WAL and fsyncs to disk
        // Even if server crashes 1ms later, payment is durable
        return payment;
    }
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

record Account(Long id, BigDecimal balance) {
    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {
            throw new InsufficientFundsException();  // Consistency: constraint enforced
        }
    }
}

@Service
public class MoneyTransferService {
    private final AccountRepository accountRepo;

    @Transactional(isolation = Isolation.SERIALIZABLE)  // All ACID properties active
    public void transfer(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId).orElseThrow();
        var toAccount = accountRepo.findById(toId).orElseThrow();

        fromAccount.debit(amount);  // Atomicity: both or neither
        toAccount.credit(amount);   // Isolation: locks prevent concurrent corruption
        accountRepo.saveAll(List.of(fromAccount, toAccount));
        // Durability: WAL persisted before commit acknowledgment
    }
}

```sql
-- Choose the isolation level for the current transaction
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

START TRANSACTION;
SELECT balance FROM accounts WHERE id = 1;  -- sees only committed data
-- A concurrent transaction's uncommitted change is invisible here (no dirty read)
UPDATE accounts SET balance = balance - 50 WHERE id = 1;
COMMIT;
```

Higher levels prevent more anomalies (dirty, non-repeatable, phantom reads) but reduce concurrency.

// Conceptual representation of WAL mechanism during a transaction
// NOT actual database code, but illustrates the WAL flow

record WALEntry(long xid, String operation, String tableName, 
                Object oldValue, Object newValue) {}

class TransactionManager {
    private List<WALEntry> writeAheadLog = new ArrayList<>();

    public void beginTransaction(long xid) {
        // Assign transaction ID, mark transaction as IN_PROGRESS in WAL
        writeAheadLog.add(new WALEntry(xid, "BEGIN", null, null, null));
    }

    public void executeUpdate(long xid, String table, Object oldVal, Object newVal) {
        // BEFORE modifying data pages, write change to WAL
        writeAheadLog.add(new WALEntry(xid, "UPDATE", table, oldVal, newVal));
        fsync(writeAheadLog);  // Force log to disk
        // NOW safe to modify in-memory data pages
    }

    public void commit(long xid) {
        writeAheadLog.add(new WALEntry(xid, "COMMIT", null, null, null));
        fsync(writeAheadLog);  // Durability: commit is durable
    }

    public void recover() {
        for (var entry : writeAheadLog) {
            if (entry.operation().equals("COMMIT")) {
                redo(entry);  // Replay committed transactions
            } else if (entry.operation().equals("BEGIN")) {
                undo(entry);  // Rollback uncommitted transactions
            }
        }
    }
}

```sql
-- ACID: one atomic transaction guarantees both rows change together
START TRANSACTION;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;  -- no other transaction ever sees a half-done transfer

-- BASE (NoSQL style): writes are accepted independently and reconciled later;
-- a reader may briefly see the old value (eventual consistency).
```

Pick ACID when correctness of every read matters (money); pick BASE when availability and scale matter more than instant consistency.
